import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CXsxtpvq.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),r={name:"guide/troubleshooting.md"};function s(i,e,d,h,l,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="cannot-connect-to-comfyui" tabindex="-1">Cannot connect to ComfyUI <a class="header-anchor" href="#cannot-connect-to-comfyui" aria-label="Permalink to &quot;Cannot connect to ComfyUI&quot;">​</a></h2><p>If the connection badge at the top right is red, ComfyUI is not running or the address differs. Start ComfyUI and check the address under <strong>Settings › ComfyUI connection</strong>.</p><h2 id="a-model-or-node-is-not-in-the-list" tabindex="-1">A model or node is &quot;not in the list&quot; <a class="header-anchor" href="#a-model-or-node-is-not-in-the-list" aria-label="Permalink to &quot;A model or node is &quot;not in the list&quot;&quot;">​</a></h2><p>After installing a model or a custom node, restart ComfyUI and reload the Asset Studio page. The image tools name any missing node. See the <a href="https://github.com/kiritype/asset-studio#dependencies" target="_blank" rel="noreferrer">README&#39;s Dependencies</a> for what is needed.</p><h2 id="the-queue-stopped" tabindex="-1">The queue stopped <a class="header-anchor" href="#the-queue-stopped" aria-label="Permalink to &quot;The queue stopped&quot;">​</a></h2><p>When a job fails the queue pauses so nothing else is lost. Read the failed job&#39;s error in the queue panel, fix the cause and resume.</p><h2 id="generation-waits-and-does-not-start" tabindex="-1">Generation waits and does not start <a class="header-anchor" href="#generation-waits-and-does-not-start" aria-label="Permalink to &quot;Generation waits and does not start&quot;">​</a></h2><p>Another task (LoRA training, VLM review) is using the GPU, or a <strong>GPU wait rule</strong> applies. The connection badge at the top right and <strong>Settings › GPU use</strong> show the reason.</p><h2 id="the-framing-goes-odd-with-the-lora-on" tabindex="-1">The framing goes odd with the LoRA on <a class="header-anchor" href="#the-framing-goes-odd-with-the-lora-on" aria-label="Permalink to &quot;The framing goes odd with the LoRA on&quot;">​</a></h2><p>A small or one-sided dataset teaches the LoRA the framing as well (two figures, extreme close-ups and so on). Grow the dataset following <a href="./lora#a-good-dataset">a good dataset</a>, and try a lower strength or an earlier epoch.</p><h2 id="log-files" tabindex="-1">Log files <a class="header-anchor" href="#log-files" aria-label="Permalink to &quot;Log files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>logs/studio.log</code></td><td>Server</td></tr><tr><td><code>logs/launcher.log</code></td><td>Start and stop</td></tr><tr><td><code>logs/lora/&lt;run name&gt;/trainer.log</code></td><td>LoRA training</td></tr></tbody></table><h2 id="backing-up-your-data" tabindex="-1">Backing up your data <a class="header-anchor" href="#backing-up-your-data" aria-label="Permalink to &quot;Backing up your data&quot;">​</a></h2><p>Back up <code>data/</code> (library, reviews, datasets, LoRA records, settings) and <code>outputs/</code> (images). Neither is part of the git repository.</p>',15)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
